function drawRapidashPastelUnicorn(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.0;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const maneLag = breathPhase - 0.4;
  const maneSwayX = Math.sin(maneLag) * 3.5;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 30 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Đuôi mây kẹo bông
  const tx = 18 + maneSwayX;
  ctx.fillStyle = '#c084fc';
  ctx.beginPath(); ctx.arc(tx,     by - 4,  10, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#7dd3fc';
  ctx.beginPath(); ctx.arc(tx + 4, by + 4,  11, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#c084fc';
  ctx.beginPath(); ctx.arc(tx + 8, by + 14, 9,  0, Math.PI * 2); ctx.fill();

  // 3. Thân
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(-2, by + 12, 14 * sX, 11 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 4. 4 Chân & Lông mây
  [-14, -6, 4, 10].forEach((x, i) => {
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.roundRect(x, by + 18, 4, 17, 2); ctx.fill();
    ctx.fillStyle = (i % 2 === 0) ? '#c084fc' : '#7dd3fc';
    ctx.beginPath(); ctx.arc(x + 2, by + 34, 4, 0, Math.PI * 2); ctx.fill();
  });

  // 5. Cổ & Bờm kẹo bông
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.roundRect(-8, by - 4, 7, 16, 3); ctx.fill();
  ctx.fillStyle = '#c084fc';
  ctx.beginPath(); ctx.arc(-12, by - 12, 10, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#7dd3fc';
  ctx.beginPath(); ctx.arc(-8,  by - 6,  11, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#c084fc';
  ctx.beginPath(); ctx.arc(-4,  by + 2,  10, 0, Math.PI * 2); ctx.fill();

  // 6. Đầu & Mõm
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(-10, by - 14, 8, 7, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-18, by - 12); ctx.lineTo(-12, by - 16); ctx.lineTo(-12, by - 10); ctx.fill();

  // 7. Sừng xoắn tím
  ctx.fillStyle = '#7c3aed';
  ctx.beginPath(); ctx.moveTo(-14, by - 18); ctx.lineTo(-22, by - 42); ctx.lineTo(-8, by - 18); ctx.fill();
  ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-14, by - 26); ctx.lineTo(-10, by - 24);
  ctx.moveTo(-18, by - 34); ctx.lineTo(-14, by - 32);
  ctx.stroke();

  // 8. Mắt biếc
  if (!blink) {
    ctx.fillStyle = '#06b6d4';
    ctx.beginPath(); ctx.arc(-10, by - 14, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-11, by - 15, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-12, by - 14); ctx.lineTo(-8, by - 14); ctx.stroke();
  }

  ctx.restore();
}
